use anyhow::Result;use serde_json::json;use synara_core::EntityId;use synara_db::Database;use synara_events::Event;
pub struct Orchestrator{pub db:Database,next_sequence:u64}
pub enum Command{CreateProject{name:String,root_path:String},CreateThread{workspace_id:EntityId,title:Option<String>},SendMessage{thread_id:EntityId,content:String}}
impl Orchestrator{pub fn new(db:Database)->Result<Self>{let existing=db.events_after(0)?.len() as u64;Ok(Self{db,next_sequence:existing+1})}pub fn dispatch(&mut self,c:Command)->Result<EntityId>{let(id,typ,payload,scope)=match c{Command::CreateProject{name,root_path}=>(EntityId::new(),"ProjectCreated",json!({"name":name,"root_path":root_path}),"project"),Command::CreateThread{workspace_id,title}=>(EntityId::new(),"ThreadCreated",json!({"workspace_id":workspace_id,"title":title}),"thread"),Command::SendMessage{thread_id,content}=>(EntityId::new(),"MessageCreated",json!({"thread_id":thread_id,"content":content}),"message")};let e=Event::new(scope,id,typ,payload,1,self.next_sequence);self.db.append_event(&e)?;self.next_sequence+=1;Ok(id)}}
